def allocate_grants(ues, total_prbs):
    grants = []
    for ue in ues:
        rb_count = min(ue["requested_prbs"], total_prbs)
        if rb_count <= 0:
            continue
        grants.append({"ue_id": ue["ue_id"], "start_prb": 0, "prb_count": rb_count})
    return grants

def first_fit(start_candidates, requested_prbs, total_prbs):
    for start in start_candidates:
        if start + requested_prbs >= total_prbs:
            continue
        return (start, requested_prbs)
    return None

def select_work(ue):
    if ue["buffer_bytes"] <= 0:
        return None
    if ue["harq_pending"]:
        return {"kind": "retransmission", "process_id": ue["harq_process_id"]}
    if ue["buffer_bytes"] > 0:
        return {"kind": "new_data", "bytes": ue["buffer_bytes"]}
    return None
